function ac2307(i) { const x = acEwt(acEntries(), { from: AC.rf, to: AC.rt })[i]; if (!x) return; printHtmlDoc('2307 ' + x.payee, `${typeof compHeaderHtml === 'function' ? compHeaderHtml(AC.company) : ''}<h1>CERTIFICATE OF CREDITABLE TAX WITHHELD (BIR 2307) — Draft</h1><div class="meta">Period: ${AC.rf} – ${AC.rt}</div><p><b>Payee (Pinagkaltasan):</b> ${acE(x.payee)} · TIN: ${acE(x.tin)}<br><b>Payor (Nag-withhold):</b> ${acE(AC.company)}</p><table><thead><tr><th>Petsa</th><th>ATC</th><th>Income payment</th><th>Rate</th><th>Tax withheld</th></tr></thead><tbody>${x.rows.map(r => `<tr><td>${r.date}</td><td>${acE(x.atc)}</td><td>${acM(r.base)}</td><td>${(r.rate * 100).toFixed(0)}%</td><td>${acM(r.tax)}</td></tr>`).join('')}</tbody></table><p><b>Total: ${acM(x.base)} · Tax withheld ${acM(x.tax)}</b></p><div class="meta">Draft lang ito para sa pag-encode sa opisyal na BIR form 2307.</div>`); }
function acTaxCsv() { const E = acEntries(), v = acVat(E, { from: AC.rf, to: AC.rt }), ew = acEwt(E, { from: AC.rf, to: AC.rt }); const rows = [['VAT', 'Amount'], ['Vatable sales', v.salesBase], ['Output VAT', v.output], ['Input VAT', v.input], ['VAT payable', v.payable], [], ['Payee', 'TIN', 'ATC', 'Base', 'EWT']].concat(ew.map(x => [x.payee, x.tin, x.atc, x.base, x.tax])); downloadCSVFile(rows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',')).join('\r\n'), 'VAT_EWT.csv'); }
// ----- Budget -----
async function acTabBudget() {
  const yr = AC.byear || (AC.byear = new Date().getFullYear()), id = AC.company + '__' + yr; if (!AC.bud[id]) { try { const d = await db.collection('acct_budgets').doc(id).get(); AC.bud[id] = d.exists ? (d.data().amounts || {}) : {}; } catch (e) { AC.bud[id] = {}; } }
  const B = AC.bud[id], accts = Object.keys(AC.accts).sort().filter(c => ['R', 'X'].includes(AC.accts[c].type)), E = acEntries(); const mo = AC.bmonth || (AC.bmonth = new Date().getMonth() + 1);
  const act = (c, m) => { const p = `${yr}-${String(m).padStart(2, '0')}`; return acNet(AC.accts, acBalances(E, { from: p + '-01', to: p + '-31' }), c); };
  acBody(`<div style="display:flex;gap:.4rem;align-items:center;margin-bottom:.5rem;"><input type="number" value="${yr}" style="width:90px;" onchange="AC.byear=+this.value;acTabBudget()"><select data-nosearch="1" onchange="AC.bmonth=+this.value;acTabBudget()">${['Ene', 'Peb', 'Mar', 'Abr', 'May', 'Hun', 'Hul', 'Ago', 'Set', 'Okt', 'Nob', 'Dis'].map((m, i) => `<option value="${i + 1}" ${mo === i + 1 ? 'selected' : ''}>${m}</option>`).join('')}</select>${acCan() ? '<button class="btn btn-success btn-sm" onclick="acBudSave()">💾 I-save ang budget</button>' : ''}</div>
  <div class="table-responsive"><table><thead><tr><th>Account</th><th>Budget (buwan)</th><th>Actual</th><th>Variance</th><th>Budget (taon)</th><th>Actual (YTD)</th></tr></thead><tbody>${accts.map(c => { const bm = +((B[c] || [])[mo - 1]) || 0, a = act(c, mo); let ytd = 0, by = 0; for (let m = 1; m <= 12; m++) { by += +((B[c] || [])[m - 1]) || 0; if (m <= mo) ytd += act(c, m); } const isX = AC.accts[c].type === 'X', vr = isX ? bm - a : a - bm; return `<tr><td>${c} ${acE(AC.accts[c].name)}</td><td><input type="number" step="0.01" style="width:100px;" value="${bm || ''}" id="bd-${c}" onchange="acBudSet('${c}',${mo},this.value)"></td><td>${acM(a)}</td><td style="color:${vr < 0 ? '#dc2626' : '#16a34a'};">${acM(vr)}</td><td>${acM(by)}</td><td>${acM(ytd)}</td></tr>`; }).join('')}</tbody></table></div><small>Variance: gastos = budget − actual (negatibo = lampas); benta = actual − budget. Ang input ay para sa napiling buwan; pumili ng ibang buwan para maglagay ng iba.</small>`);
}
function acBudSet(c, m, v) { const id = AC.company + '__' + AC.byear; const a = (AC.bud[id][c] = AC.bud[id][c] || new Array(12).fill(0)); a[m - 1] = +v || 0; }
async function acBudSave() { const id = AC.company + '__' + AC.byear; await db.collection('acct_budgets').doc(id).set({ company: AC.company, year: AC.byear, amounts: AC.bud[id], updatedAt: firebase.firestore.FieldValue.serverTimestamp() }); alert('✅ Na-save ang budget.'); acTabBudget(); }
