function acTabRecur() {
  const L = AC.recur.filter(r => r.company === AC.company);
  acBody(`<div style="display:flex;gap:.4rem;margin-bottom:.5rem;">${acCan() ? '<button class="btn btn-success btn-sm" onclick="acRecForm()">➕ Bagong recurring</button><button class="btn btn-primary btn-sm" onclick="acRecRun()">▶️ Patakbuhin ang due</button>' : ''}</div>${L.map(r => `<div class="card" style="margin-bottom:.4rem;"><b>${acE(r.name)}</b> · bawat ika-${r.day} · simula ${r.start} ${r.active === false ? '· <i>(tigil)</i>' : ''}<br><small>${r.lines.map(l => `${l.acct} ${l.debit ? 'Dr ' + acM(l.debit) : 'Cr ' + acM(l.credit)}`).join(' · ')}</small> ${acCan() ? `<button class="btn btn-sm btn-secondary" onclick="acRecToggle('${r.id}')">${r.active === false ? '▶️ Ituloy' : '⏸️ Ihinto'}</button>` : ''}</div>`).join('') || '<small>Wala pa. Halimbawa: Renta, Depreciation, Internet.</small>'}`);
}
function acRecForm() { AC.draft = { name: '', day: 1, start: acYM(acToday()), lines: [{ acct: '', debit: '', credit: '' }, { acct: '', debit: '', credit: '' }] }; acRecRender(); }
function acRecRender() { const D = AC.draft; arModal(`<h3>🔁 Recurring Entry</h3><div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:.4rem;"><div><label>Pangalan</label><input value="${acE(D.name)}" oninput="AC.draft.name=this.value"></div><div><label>Araw ng buwan</label><input type="number" min="1" max="28" value="${D.day}" onchange="AC.draft.day=+this.value"></div><div><label>Simula (YYYY-MM)</label><input value="${D.start}" onchange="AC.draft.start=this.value"></div></div><table style="margin-top:.4rem;"><tbody>${D.lines.map((l, i) => `<tr><td><select onchange="AC.draft.lines[${i}].acct=this.value">${acOpts(l.acct)}</select></td><td><input type="number" step="0.01" placeholder="Debit" style="width:100px;" value="${l.debit}" onchange="AC.draft.lines[${i}].debit=this.value"></td><td><input type="number" step="0.01" placeholder="Credit" style="width:100px;" value="${l.credit}" onchange="AC.draft.lines[${i}].credit=this.value"></td></tr>`).join('')}</tbody></table><button class="btn btn-sm btn-secondary" onclick="AC.draft.lines.push({acct:'',debit:'',credit:''});acRecRender()">➕ Linya</button> <button class="btn btn-success" onclick="acRecSave()">💾 I-save</button>`); }
async function acRecSave() { const D = AC.draft, lines = D.lines.filter(l => l.acct).map(l => ({ acct: l.acct, debit: acR2(l.debit), credit: acR2(l.credit), desc: D.name })); const er = acValidate(lines, AC.accts); if (er || !D.name.trim() || !/^\d{4}-\d{2}$/.test(D.start)) { alert(er || 'Ilagay ang pangalan at simula (YYYY-MM).'); return; } const doc = { company: AC.company, name: D.name.trim(), day: Math.min(28, Math.max(1, D.day || 1)), start: D.start, lines, active: true }; const r = await db.collection('acct_recurring').add(doc); AC.recur.push({ id: r.id, ...doc }); arCloseModal(); acTabRecur(); }
async function acRecToggle(id) { const r = AC.recur.find(x => x.id === id); r.active = r.active === false; await db.collection('acct_recurring').doc(id).update({ active: r.active }); acTabRecur(); }
async function acRecRun() { let n = 0, skip = 0; const nowYM = acYM(acToday()); for (const r of AC.recur.filter(x => x.company === AC.company && x.active !== false)) for (const ym of acRecMonths(r, nowYM)) { try { const id = await acPost({ company: r.company, date: `${ym}-${String(r.day).padStart(2, '0')}`, memo: r.name + ' ' + ym, source: 'recurring', lines: r.lines }, `REC-${r.id}-${ym}`); id ? n++ : 0; } catch (e) { skip++; } } alert(`✅ Nagawa: ${n}` + (skip ? ` · Na-skip (naka-lock/may mali): ${skip}` : '')); acRender(); }
// ----- Setup -----
function acTabSetup() {
  const co = AC.company, accts = Object.keys(AC.accts).sort();
  acBody(`<div class="card" style="background:#f8fafc;"><b>Chart of Accounts</b> (pareho sa lahat ng company)<div style="margin:.4rem 0;display:flex;gap:.4rem;flex-wrap:wrap;">${acCan() ? `${accts.length ? '' : '<button class="btn btn-success btn-sm" onclick="acSeed()">✨ Gumawa ng Default COA (Philippine)</button>'}<button class="btn btn-secondary btn-sm" onclick="acAcctForm()">➕ Account</button><button class="btn btn-secondary btn-sm" onclick="acCoaImport()">📤 Import COA CSV</button>` : ''}<button class="btn btn-secondary btn-sm" onclick="downloadCSVFile('Code,Name,Type,Bank\\r\\n1010,Cash in Bank - BDO,Asset,Y\\r\\n6100,Rent Expense,Expense,','COA_Template.csv')">📄 Template</button></div>
  <div class="table-responsive" style="max-height:260px;overflow:auto;"><table><thead><tr><th>Code</th><th>Pangalan</th><th>Type</th><th></th></tr></thead><tbody>${accts.map(c => `<tr><td>${c}</td><td>${acE(AC.accts[c].name)}${AC.accts[c].bank ? ' 🏦' : ''}${AC.accts[c].active === false ? ' <i>(inactive)</i>' : ''}</td><td>${AC_TYPES[AC.accts[c].type]}</td><td>${acCan() ? `<button class="btn btn-sm btn-secondary" onclick="acAcctForm('${c}')">✏️</button>` : ''}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="card" style="background:#f8fafc;"><b>${acE(co)} — Settings</b><br><label style="display:flex;gap:.3rem;"><input type="checkbox" style="width:auto;" ${AC.cfg.vat && AC.cfg.vat[co] ? 'checked' : ''} onchange="acCfgVat(this.checked)"> VAT-registered ang company na ito</label>
  <div style="margin-top:.4rem;"><label>🔒 I-lock ang books hanggang (petsa) — month-end close</label><input type="date" value="${(AC.cfg.locked || {})[co] || ''}" onchange="acCfgLock(this.value)"> <small>Walang puwedeng ma-post na entry sa o bago ang petsang ito. Tanggalin ang petsa para i-unlock.</small></div>
  <div style="margin-top:.4rem;"><label>Default cash/bank account sa pag-sync</label><select onchange="AC.cfg.cash=this.value;acSaveCfg()">${acOpts(AC.cfg.cash || '1010', acPay)}</select></div>
  <div style="margin-top:.4rem;"><label>Company ng lumang General Ledger (cash ledger ng ERP)</label><select onchange="AC.cfg.glCompany=this.value;acSaveCfg()"><option value="">— wala (huwag i-sync) —</option>${AC.companies.map(c => `<option ${AC.cfg.glCompany === c ? 'selected' : ''}>${acE(c)}</option>`).join('')}</select></div></div>
  <div class="card" style="background:#f8fafc;"><b>Awtomatikong galing sa ERP</b><br><small>Kusang nagpo-post pagbukas ng tab na ito (walang double): lumang General Ledger (payroll, bayad sa PO), AR orders at bayad ng customers.</small><div style="margin-top:.4rem;display:flex;gap:.4rem;flex-wrap:wrap;"><button class="btn btn-primary btn-sm" onclick="acSyncClick()">🔄 I-sync ngayon</button><button class="btn btn-secondary btn-sm" onclick="acJournalImport()">📤 Import Journal CSV (mula QuickBooks)</button><button class="btn btn-secondary btn-sm" onclick="downloadCSVFile('Date,Ref,Memo,Account,Debit,Credit,Description\\r\\n2026-01-01,OB-1,Opening balance,1010,50000,0,Bank\\r\\n2026-01-01,OB-1,Opening balance,3000,0,50000,Capital','Journal_Template.csv')">📄 Template</button></div><div id="ac-syncmsg" style="font-size:.82rem;margin-top:.3rem;"></div></div>`);
}
async function acSeed() { const b = db.batch(); AC_DEFAULT.forEach(a => b.set(db.collection('acct_accounts').doc(a[0]), { code: a[0], name: a[1], type: a[2], bank: !!a[3], active: true })); await b.commit(); await acLoad(); acRender(); }
function acAcctForm(code) { const a = code ? AC.accts[code] : { code: '', name: '', type: 'X', bank: false, active: true }; arModal(`<h3>${code ? '✏️' : '➕'} Account</h3><div style="display:grid;gap:.4rem;"><div><label>Code</label><input id="aa-c" value="${acE(a.code)}" ${code ? 'disabled' : ''}></div><div><label>Pangalan</label><input id="aa-n" value="${acE(a.name)}"></div><div><label>Type</label><select id="aa-t" data-nosearch="1">${Object.keys(AC_TYPES).map(t => `<option value="${t}" ${a.type === t ? 'selected' : ''}>${AC_TYPES[t]}</option>`).join('')}</select></div><label><input type="checkbox" id="aa-b" style="width:auto;" ${a.bank ? 'checked' : ''}> Bank/Cash account (lalabas sa Bank Rec at bayaran)</label><label><input type="checkbox" id="aa-a" style="width:auto;" ${a.active !== false ? 'checked' : ''}> Active</label></div><button class="btn btn-success" style="margin-top:.5rem;" onclick="acAcctSave()">💾 I-save</button>`); }
async function acAcctSave() { const g = id => document.getElementById(id), c = g('aa-c').value.trim(), n = g('aa-n').value.trim(); if (!c || !n) { alert('Ilagay ang code at pangalan.'); return; } const doc = { code: c, name: n, type: g('aa-t').value, bank: g('aa-b').checked, active: g('aa-a').checked }; await db.collection('acct_accounts').doc(c).set(doc); AC.accts[c] = doc; arCloseModal(); acRender(); }
async function acCoaImport() { const t = await pickCSVFile(); if (!t) return; const rows = csvToObjects(t); let n = 0, bad = 0; for (const r of rows) { const c = String(r.code || '').trim(), nm = String(r.name || '').trim(), ty = acCoaType(r.type); if (!c || !nm || !ty) { bad++; continue; } const doc = { code: c, name: nm, type: ty, bank: /^(y|yes|1|true)/i.test(r.bank || ''), active: true }; await db.collection('acct_accounts').doc(c).set(doc, { merge: true }); AC.accts[c] = Object.assign(AC.accts[c] || {}, doc); n++; } alert(`✅ ${n} account na-import` + (bad ? `, ${bad} row na may kulang (Code, Name, Type)` : '')); acRender(); }
async function acCfgVat(v) { AC.cfg.vat = AC.cfg.vat || {}; AC.cfg.vat[AC.company] = v; await acSaveCfg(); }
async function acCfgLock(d) { if (typeof normalizeRole === 'function' && normalizeRole((getCurrentUser() || {}).role) !== 'admin') { alert('Admin lang ang puwedeng mag-lock/unlock.'); acRender(); return; } AC.cfg.locked = AC.cfg.locked || {}; if (d) AC.cfg.locked[AC.company] = d; else delete AC.cfg.locked[AC.company]; await acSaveCfg(); acRender(); }
async function acJournalImport() { const t = await pickCSVFile(); if (!t) return; const r = acJournalFromRows(csvToObjects(t), AC.accts, AC.company); let msg = `${r.entries.length} journal ang ipapasok sa ${AC.company}.` + (r.errs.length ? `\n\nMga problema (${r.errs.length}):\n` + r.errs.slice(0, 8).join('\n') : ''); if (!r.entries.length) { alert(msg); return; } if (!await uiConfirm(msg + '\n\nTuloy?')) return; let ok = 0; for (const e of r.entries) { try { e.source = 'import'; await acPost(e); ok++; } catch (er) { msg += '\n' + er.message; } } alert(`✅ Na-post: ${ok}`); acRender(); }
// ----- ERP sync (idempotent: deterministic ids) -----
function acGlMap(t, cash) { t = String(t || ''); if (/payroll|salary|sahod/i.test(t)) return { dr: '6000', cr: cash }; if (/down ?payment|^dp\b|advance/i.test(t)) return { dr: '1150', cr: cash }; if (/vendor|po|payable|supplier|ap\b/i.test(t)) return { dr: '2000', cr: cash }; return null; }
async function acSyncGL() { const co = AC.cfg.glCompany; if (!co) return 0; const snap = await db.collection('general_ledger').get(); let n = 0; const cash = AC.cfg.cash || '1010'; const have = new Set(AC.all.map(e => e.id));
  for (const d of snap.docs) { const id = 'GL-' + d.id; if (have.has(id)) continue; const t = d.data(), dr = +t.debit || 0, cr = +t.credit || 0, ts = t.timestamp && t.timestamp.toDate ? t.timestamp.toDate().toISOString().slice(0, 10) : acToday(); if (!dr && !cr) continue; let lines; const m = acGlMap(t.type + ' ' + (t.ref || ''), cash);
    if (cr > 0) lines = [{ acct: m ? m.dr : '9999', debit: cr, credit: 0, desc: t.ref || t.type }, { acct: cash, debit: 0, credit: cr, desc: t.type }]; else lines = [{ acct: cash, debit: dr, credit: 0, desc: t.type }, { acct: '9999', debit: 0, credit: dr, desc: t.ref || t.type }];
    try { if (await acPost({ company: co, date: ts, memo: `${t.type || 'GL'} — ${t.ref || ''}`, ref: d.id, source: 'ERP GL', lines }, id)) n++; } catch (e) { /* naka-lock o kulang ang COA */ } } return n; }
async function acSyncAR() { const [os, as] = await Promise.all([db.collection('orders').orderBy('createdAt', 'desc').limit(500).get(), db.collection('ar_accounts').get()]); const accts = {}; as.forEach(d => accts[d.id] = d.data()); let n = 0, noco = 0; const have = new Set(AC.all.map(e => e.id)), cashD = AC.cfg.cash || '1010';
  for (const d of os.docs) { const o = { id: d.id, ...d.data() }; if (typeof arIncluded === 'function' && !arIncluded(o)) continue; const total = +o.totalAmount || 0; if (total <= 0) continue; const co0 = typeof arCompanyOf === 'function' ? arCompanyOf(o) : '', co = AC.companies.find(c => hubKey(c) === hubKey(co0)); if (!co) { noco++; continue; }
    const dt = String(o.targetDeliveryDate || '').slice(0, 10) || (o.createdAt && o.createdAt.toDate ? o.createdAt.toDate().toISOString().slice(0, 10) : acToday()), vat = AC.cfg.vat && AC.cfg.vat[co], net = vat ? acR2(total / 1.12) : total, vv = acR2(total - net);
    try { const L = [{ acct: '1100', debit: total, credit: 0, desc: o.customerName || o.branchName || '' }, { acct: '4000', debit: 0, credit: net, desc: o.siNumber || d.id }]; if (vv) L.push({ acct: '2100', debit: 0, credit: vv, desc: 'Output VAT' }); if (!have.has('AR-' + d.id) && await acPost({ company: co, date: dt, memo: `Benta ${o.siNumber || d.id} — ${o.customerName || o.branchName || ''}`, ref: o.siNumber || d.id, source: 'ERP AR', lines: L }, 'AR-' + d.id)) n++; } catch (e) {}
    ((accts[d.id] || {}).payments || []).forEach((p, i) => { p._i = i; }); for (const p of ((accts[d.id] || {}).payments || [])) { const a = acR2(p.amount); if (p.voided || !a) continue; const pd = String(p.date || p.paidAt || '').slice(0, 10) || dt, cashAcct = /cash/i.test(p.method || p.mode || '') ? '1000' : cashD; try { if (!have.has(`ARP-${d.id}-${p._i}`) && await acPost({ company: co, date: /^\d{4}-\d{2}-\d{2}$/.test(pd) ? pd : dt, memo: `Bayad ${o.siNumber || d.id}`, ref: o.siNumber || d.id, source: 'ERP AR', lines: [{ acct: cashAcct, debit: a, credit: 0, desc: o.customerName || '' }, { acct: '1100', debit: 0, credit: a, desc: o.siNumber || d.id }] }, `ARP-${d.id}-${p._i}`)) n++; } catch (e) {} } }
  return { n, noco }; }
async function acAutoSync() { if (!acCan() || !Object.keys(AC.accts).length || window.__acSyncing) return; window.__acSyncing = true; try { const g = await acSyncGL(), a = await acSyncAR(); if ((g || a.n) && AC.tab === 'journal') acTabJournal(); const el = document.getElementById('ac-syncmsg'); if (el) el.textContent = `Huling sync: GL ${g} · AR ${a.n}` + (a.noco ? ` · ${a.noco} order na walang company (hindi na-post)` : ''); } finally { window.__acSyncing = false; } }
async function acSyncClick() { const el = document.getElementById('ac-syncmsg'); if (el) el.textContent = 'Nagsi-sync...'; window.__acSyncing = false; await acLoad(); await acAutoSync(); acRender(); alert('✅ Tapos ang sync. Tingnan ang Journal (source: ERP GL / ERP AR). Ang mga hindi tukoy na GL entry ay napunta sa 9999 Suspense para i-reclassify.'); }
